--
-- Table structure for table `releases`
--

DROP TABLE IF EXISTS `releases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `releases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `channel` enum('directory','promos','status') NOT NULL,
  `version` varchar(32) NOT NULL,
  `seq` int(10) unsigned NOT NULL,
  `sha256` char(64) NOT NULL,
  `bytes` int(10) unsigned NOT NULL,
  `path` varchar(255) NOT NULL,
  `revs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`revs`)),
  `stats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`stats`)),
  `diff` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`diff`)),
  `validation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`validation`)),
  `notes` varchar(500) DEFAULT NULL,
  `is_live` tinyint(1) NOT NULL DEFAULT 0,
  `rolled_back_from` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rel` (`channel`,`version`),
  UNIQUE KEY `uq_rel_seq` (`channel`,`seq`),
  KEY `idx_rel_live` (`channel`,`is_live`),
  KEY `fk_rel_rb` (`rolled_back_from`),
  KEY `fk_rel_user` (`created_by`),
  CONSTRAINT `fk_rel_rb` FOREIGN KEY (`rolled_back_from`) REFERENCES `releases` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rel_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

